edit: included manual @
<a href="https://www.codeigniter.com/userguide3/database/query_builder.html" rel="nofollow noreferrer">https://www.codeigniter.com/userguide3/database/query_builder.html</a></p>

<p>more edits below:</p>

<pre><code>&lt;?php

    class Home extends CI_Controller{

        public function index(){
            $this-&gt;load-&gt;model('Crudmodel');
            $data['records'] = $this-&gt;Crudmodel-&gt;getRecords();
            $this-&gt;load-&gt;view('home', $data['records']);

        }
    }
?&gt;
</code></pre>

